.forensic-sidebar {
  width: 250px;
  height: 100vh;
  background-color: #0b1117;
  color: #ffffff;
  display: flex;
  flex-direction: column;
  position: fixed;
  left: 0;
  top: 0;
  z-index: 9999;
  border-right: 1px solid #30363d;
  margin: 0;
  padding: 0;
}

.sidebar-header {
  padding: 25px 20px;
  font-weight: 700;
  font-size: 1.4rem;
  letter-spacing: 1px;
  background: #161b22;
  border-bottom: 1px solid #30363d;
}

.nav-menu {
  display: flex;
  flex-direction: column;
  padding: 15px 10px;
  gap: 8px;
}

.nav-menu button {
  background: transparent;
  border: none;
  color: #c9d1d9;
  text-align: left;
  padding: 12px 15px;
  cursor: pointer;
  border-radius: 6px;
  font-family: sans-serif;
  font-size: 14px;
  transition: all 0.2s ease;
}

.nav-menu button:hover {
  background-color: #21262d;
  color: #58a6ff;
}

