appsmith.onReady(() => {
  const rawData = appsmith.model.dashboardData;
  if (!rawData || rawData.length === 0) {
    console.warn("Waiting for data...");
    return;
  }
  appsmith.onReady(() => {
    const rawData = appsmith.model.dashboardData;
    if (!rawData || rawData.length === 0) return;

    // --- 1. DATA AGGREGATION ---
    let kpis = {
      total: rawData.length,
      highRisk: 0,
      duplicates: 0,
      compliance: 0,
      vendorsFlagged: new Set()
    };
    let lists = {
      vendors: new Set(),
      missingGstin: [],
      violations: new Set(),
      weekend: []
    };
    let highRiskTransactions = [];

    // Aggregators for Charts
    let vendorStats = {}; // For Risk Matrix
    let trendData = {}; // For Trend Line

    rawData.forEach(row => {
      let risk = (row.transaction_risk || "").toUpperCase();
      let isHighRisk = risk === "HIGH" || risk === "CRITICAL";
      if (isHighRisk) {
        kpis.highRisk++;
        highRiskTransactions.push(row);
      }

      // Process Flags
      let flags = [];
      try {
        flags = typeof row.flags_detected === 'string' ? JSON.parse(row.flags_detected) : row.flags_detected || [];
      } catch (e) {}
      flags.forEach(f => {
        let type = typeof f === 'object' ? f.type : f;
        kpis.compliance++;
        lists.violations.add(type);
        if (type.toLowerCase().includes("duplicate")) kpis.duplicates++;
      });

      // Vendor Logic
      if (row.vendor_blacklisted === true || (row.vendor_risk || "").toUpperCase() === "HIGH") {
        kpis.vendorsFlagged.add(row.vendor_id);
        lists.vendors.add(`${row.vendor_id} (${row.vendor_name || 'Unknown'})`);
      }

      // Aggregate Vendor Stats for Matrix
      const vId = row.vendor_name || "Unknown";
      if (!vendorStats[vId]) vendorStats[vId] = {
        volume: 0,
        riskScore: 0
      };
      vendorStats[vId].volume += 1;
      vendorStats[vId].riskScore += risk === 'CRITICAL' ? 4 : risk === 'HIGH' ? 3 : risk === 'MEDIUM' ? 2 : 1;

      // Aggregate Trend Data
      const date = row.invoice_date || "Unknown";
      if (!trendData[date]) trendData[date] = {
        total: 0,
        flagged: 0
      };
      trendData[date].total++;
      if (isHighRisk || flags.length > 0) trendData[date].flagged++;

      // Lists: Missing GSTIN & Weekend
      if (!row.gstin || row.gstin.trim() === "") lists.missingGstin.push(row.invoice_id);
      if (row.invoice_date) {
        let d = new Date(row.invoice_date);
        if (d.getDay() === 0 || d.getDay() === 6) {
          let dayStr = d.getDay() === 0 ? "Sun" : "Sat";
          lists.weekend.push(`${row.invoice_id} (${dayStr} ${Math.floor(Math.random() * 12 + 1)} PM)`);
        }
      }
    });

    // --- 2. UPDATE DOM (KPIs & LISTS) ---
    const setText = (id, text) => {
      if (document.getElementById(id)) document.getElementById(id).innerText = text;
    };
    setText('kpi-total', kpis.total);
    setText('kpi-risk', kpis.highRisk);
    setText('kpi-dup', kpis.duplicates);
    setText('kpi-comp', kpis.compliance);
    setText('kpi-ven', kpis.vendorsFlagged.size);
    const renderList = (id, items) => {
      const el = document.getElementById(id);
      if (el) el.innerHTML = items.length > 0 ? items.slice(0, 3).map(i => `<li>${i}</li>`).join('') : "<li>None detected</li>";
    };
    renderList('list-high-risk-vendors', Array.from(lists.vendors));
    renderList('list-missing-gstin', lists.missingGstin);
    renderList('list-policy', Array.from(lists.violations));
    renderList('list-weekend', lists.weekend);

    // --- 3. MOCK TABLES (As seen in your screenshot) ---
    const queueBody = document.querySelector('#queue-table tbody');
    if (queueBody) {
      queueBody.innerHTML = (highRiskTransactions.length > 0 ? highRiskTransactions : rawData).slice(0, 4).map((row, i) => `
            <tr><td><b>EQ-${101 + i}</b></td><td>${row.vendor_id}</td><td>Compliance Flag</td><td style="color:#d32f2f; font-weight:bold;">Escalated</td></tr>
        `).join('');
    }
    const logsBody = document.querySelector('#logs-table tbody');
    if (logsBody) {
      logsBody.innerHTML = rawData.slice(0, 3).map(row => `
            <tr><td>${new Date().toLocaleTimeString()}</td><td><b>Rule Engine Agent</b></td><td>Analyzed ${row.invoice_id}</td></tr>
        `).join('');
    }

    // --- 4. RENDER CHARTS ---
    renderDashboardCharts(vendorStats, trendData);
  });
  function renderDashboardCharts(vendorStats, trendData) {
    // Vendor Risk Matrix
    new Chart(document.getElementById('riskMatrixChart'), {
      type: 'bubble',
      data: {
        datasets: Object.keys(vendorStats).map((name, i) => ({
          label: name,
          data: [{
            x: vendorStats[name].volume,
            y: vendorStats[name].riskScore / vendorStats[name].volume,
            r: 10
          }],
          backgroundColor: 'rgba(123, 31, 162, 0.6)'
        }))
      },
      options: {
        scales: {
          x: {
            title: {
              display: true,
              text: 'Transaction Volume'
            }
          },
          y: {
            title: {
              display: true,
              text: 'Avg Risk Score'
            }
          }
        }
      }
    });

    // Anomaly Trend
    const dates = Object.keys(trendData).sort();
    new Chart(document.getElementById('anomalyTrendChart'), {
      type: 'line',
      data: {
        labels: dates,
        datasets: [{
          label: 'Total Invoices',
          data: dates.map(d => trendData[d].total),
          borderColor: '#1976d2',
          fill: false
        }, {
          label: 'Flagged',
          data: dates.map(d => trendData[d].flagged),
          borderColor: '#d32f2f',
          fill: false
        }]
      }
    });
  }
  // --- 1. INITIALIZE TRACKERS ---
  let kpis = {
    total: rawData.length,
    highRisk: 0,
    duplicates: 0,
    compliance: 0,
    vendorsFlagged: new Set()
  };
  let lists = {
    vendors: new Set(),
    missingGstin: [],
    violations: new Set(),
    weekend: []
  };
  let highRiskTransactions = [];

  // --- 2. PROCESS DATABASE ROWS ---
  rawData.forEach(row => {
    // Adjusting for your specific column names: transaction_risk
    let risk = (row.transaction_risk || "").toUpperCase();
    let isHighRisk = risk === "HIGH" || risk === "CRITICAL";
    if (isHighRisk) {
      kpis.highRisk++;
      highRiskTransactions.push(row);
    }

    // Parse flags_detected JSON payload
    let flags = [];
    if (row.flags_detected) {
      try {
        flags = typeof row.flags_detected === 'string' ? JSON.parse(row.flags_detected) : row.flags_detected;
        if (!Array.isArray(flags)) flags = [];
      } catch (e) {}
    }
    flags.forEach(f => {
      let type = typeof f === 'object' && f !== null ? f.type : f;
      if (!type) return;
      kpis.compliance++;
      lists.violations.add(type);
      if (type.toLowerCase().includes("duplicate")) {
        kpis.duplicates++;
      }
    });

    // Adjusting for your specific column names: vendor_blacklisted and vendor_risk
    if (row.vendor_blacklisted === true || (row.vendor_risk || "").toUpperCase() === "HIGH") {
      if (row.vendor_id) {
        kpis.vendorsFlagged.add(row.vendor_id);
        lists.vendors.add(`${row.vendor_id} (${row.vendor_name || 'Unknown'})`);
      }
    }

    // Missing GSTIN check
    if (!row.gstin || row.gstin.trim() === "") {
      if (lists.missingGstin.length < 5) lists.missingGstin.push(row.invoice_id);
    }

    // Weekend Entries (Mocking the time based on invoice_date)
    if (row.invoice_date) {
      let d = new Date(row.invoice_date);
      let day = d.getDay(); // 0 is Sunday, 6 is Saturday
      if (day === 0 || day === 6) {
        if (lists.weekend.length < 5) {
          let dayStr = day === 0 ? "Sun" : "Sat";
          let mockTime = Math.floor(Math.random() * 12 + 1) + (Math.random() > 0.5 ? " AM" : " PM");
          lists.weekend.push(`${row.invoice_id} (${dayStr} ${mockTime})`);
        }
      }
    }
  });

  // --- 3. DOM UPDATES: KPIs ---
  const setText = (id, text) => {
    let el = document.getElementById(id);
    if (el) el.innerText = text;
  };
  setText('kpi-total', kpis.total.toLocaleString());
  setText('kpi-risk', kpis.highRisk.toLocaleString());
  setText('kpi-dup', kpis.duplicates.toLocaleString());
  setText('kpi-comp', kpis.compliance.toLocaleString());
  setText('kpi-ven', kpis.vendorsFlagged.size.toLocaleString());

  // --- 4. DOM UPDATES: LISTS ---
  const renderList = (id, items) => {
    const el = document.getElementById(id);
    if (el) el.innerHTML = Array.from(items).length > 0 ? Array.from(items).slice(0, 5).map(item => `<li>${item}</li>`).join('') : "<li>None detected</li>";
  };
  renderList('list-high-risk-vendors', lists.vendors);
  renderList('list-missing-gstin', lists.missingGstin);
  renderList('list-policy', lists.violations);
  renderList('list-weekend', lists.weekend);

  // --- 5. DOM UPDATES: MOCKED TABLES ---

  // MOCK: Agent Flag Escalation Queue
  const queueBody = document.querySelector('#queue-table tbody');
  if (queueBody) {
    queueBody.innerHTML = '';
    const statuses = ["Pending Review", "Escalated", "Open"];

    // Show high risk items or recent items if no high risk
    const displayRows = highRiskTransactions.length > 0 ? highRiskTransactions : rawData.slice(0, 4);
    displayRows.slice(0, 4).forEach((row, index) => {
      const randomStatus = statuses[Math.floor(Math.random() * statuses.length)];
      const statusColor = randomStatus === 'Escalated' ? '#d32f2f' : randomStatus === 'Open' ? '#f57c00' : '#1976d2';
      let issue = "Compliance Flag";
      try {
        let parsed = typeof row.flags_detected === 'string' ? JSON.parse(row.flags_detected) : row.flags_detected;
        if (parsed && parsed.length > 0) issue = parsed[0].type || issue;
      } catch (e) {}
      queueBody.innerHTML += `
                <tr>
                    <td><strong>EQ-${100 + index + 1}</strong></td>
                    <td>${row.vendor_id || row.invoice_id}</td>
                    <td>${issue}</td>
                    <td style="color: ${statusColor}; font-weight: bold;">${randomStatus}</td>
                </tr>
            `;
    });
  }

  // MOCK: Activity Logs
  const logsBody = document.querySelector('#logs-table tbody');
  if (logsBody) {
    logsBody.innerHTML = '';
    const agents = ["Document Matching Agent", "Rule Engine Agent", "Compliance Agent"];
    rawData.slice(0, 3).forEach((row, index) => {
      const randomAgent = agents[Math.floor(Math.random() * agents.length)];
      const timeStr = new Date().toLocaleTimeString([], {
        hour: '2-digit',
        minute: '2-digit',
        second: '2-digit'
      });
      let actionText = `Analyzed transaction ${row.invoice_id}`;
      if (row.transaction_risk === 'HIGH' || row.transaction_risk === 'CRITICAL') actionText = `Flagged ${row.invoice_id} for high risk anomalies.`;else if (!row.gstin) actionText = `Failed GSTIN validation for vendor ${row.vendor_id || 'Unknown'}.`;
      logsBody.innerHTML += `
                <tr>
                    <td style="color: #666;">${timeStr}</td>
                    <td><strong>${randomAgent}</strong></td>
                    <td>${actionText}</td>
                </tr>
            `;
    });
  }
});

