function uploadFile(connectorId, inputElement) {
  if (inputElement.files && inputElement.files.length > 0) {
    const fileName = inputElement.files[0].name;
    const connector = document.getElementById(connectorId);
    connector.classList.remove('pending');
    connector.classList.add('active');
    connector.querySelector('.status-text').textContent = `Connected: ${fileName}`;
  }
}

const ingestionData = {
  kpis: { uploaded: "1,245,091", standardized: "1,180,442", errors: "14,201", pending: "50,448" },
  preview: [
    { id: "INV-001", file: "invoices_Q3.xlsx", source: "ERP Export", status: "Processing", records: "450,000", connector: "Active" },
    { id: "PO-001", file: "po_master_v2.csv", source: "Procurement", status: "Complete", records: "120,500", connector: "Active" },
    { id: "GRN-001", file: "grn_receipts.json", source: "Warehouse", status: "Processing", records: "85,000", connector: "Active" },
    { id: "TAX-001", file: "tax_codes_fy26.csv", source: "Compliance", status: "Failed", records: "4,200", connector: "Inactive" }
  ]
};

document.getElementById('kpi-uploaded').textContent = ingestionData.kpis.uploaded;
document.getElementById('kpi-standard').textContent = ingestionData.kpis.standardized;
document.getElementById('kpi-errors').textContent = ingestionData.kpis.errors;
document.getElementById('kpi-pending').textContent = ingestionData.kpis.pending;

const populatePreviewTable = () => {
  const tbody = document.querySelector('#preview-table tbody');
  tbody.innerHTML = "";
  ingestionData.preview.forEach(p => {
    let statusClass = p.status === "Failed" ? "status-failed" : (p.status === "Complete" ? "status-complete" : "status-processing");
    let connectorStyle = p.connector === "Inactive" ? "color: #de350b;" : "color: #00875a;";
    tbody.innerHTML += `<tr>
      <td><strong>${p.id}</strong></td>
      <td>${p.file}</td>
      <td>${p.source}</td>
      <td><span class="status-pill ${statusClass}">${p.status}</span></td>
      <td>${p.records}</td>
      <td style="${connectorStyle}"><strong>${p.connector}</strong></td>
    </tr>`;
  });
};

populatePreviewTable();

