const engineData = {
  kpis: {
    rules: "42",
    violations: "3,104",
    highRisk: "215",
    escalated: "84"
  },
  feed: [{
    id: "TXN-9912",
    rule: "Approval Hierarchy",
    entity: "John Smith (Mgr)",
    risk: "High"
  }, {
    id: "TXN-9915",
    rule: "Round Value Check",
    entity: "Vendor-441",
    risk: "Medium"
  }, {
    id: "TXN-9918",
    rule: "Weekend Posting",
    entity: "System Account",
    risk: "High"
  }, {
    id: "TXN-9922",
    rule: "Duplicate Vendor IP",
    entity: "Vendor-882",
    risk: "Medium"
  }],
  effectiveness: [{
    rule: "Round Value Check",
    count: "1,420",
    valid: "88%"
  }, {
    rule: "Approval Hierarchy",
    count: "842",
    valid: "95%"
  }, {
    rule: "Weekend Posting",
    count: "610",
    valid: "91%"
  }, {
    rule: "Duplicate Vendor IP",
    count: "232",
    valid: "45%"
  }]
};
document.getElementById('kpi-rules').textContent = engineData.kpis.rules;
document.getElementById('kpi-violations').textContent = engineData.kpis.violations;
document.getElementById('kpi-high-risk').textContent = engineData.kpis.highRisk;
document.getElementById('kpi-escalated').textContent = engineData.kpis.escalated;
const popViolations = () => {
  const tbody = document.querySelector('#violation-table tbody');
  tbody.innerHTML = "";
  engineData.feed.forEach(v => {
    let riskClass = v.risk === "High" ? "risk-high" : "risk-med";
    tbody.innerHTML += `<tr>
      <td><strong>${v.id}</strong></td>
      <td>${v.rule}</td>
      <td>${v.entity}</td>
      <td><span class="risk-pill ${riskClass}">${v.risk}</span></td>
    </tr>`;
  });
};
const popEffectiveness = () => {
  const tbody = document.querySelector('#effectiveness-table tbody');
  tbody.innerHTML = "";
  engineData.effectiveness.forEach(e => {
    tbody.innerHTML += `<tr>
      <td><strong>${e.rule}</strong></td>
      <td>${e.count}</td>
      <td style="color: var(--success-green); font-weight: 600;">${e.valid}</td>
    </tr>`;
  });
};
popViolations();
popEffectiveness();

