appsmith.onReady(() => {
  const rawData = appsmith.model.invoices;
  if (!rawData || rawData.length === 0) {
    document.body.innerHTML = '<div style="padding: 20px; font-family: sans-serif; color: #666;">Waiting for database records...</div>';
    return;
  }
  let missingGstinCount = 0;
  let invalidGstinCount = 0;
  let taxMismatchCount = 0;
  let eligibleInvoices = 0;
  let issuesTableData = [];

  // Data structures for Charts
  let vendorViolations = {};
  let trendData = {};
  rawData.forEach(row => {
    let hasIssue = false;
    let currentIssue = "None";
    if (!row.gstin || row.gstin.trim() === '') {
      missingGstinCount++;
      hasIssue = true;
      currentIssue = "Missing GSTIN";
    }
    let flagTypes = [];
    if (row.flags_detected) {
      try {
        let parsedFlags = typeof row.flags_detected === 'string' ? JSON.parse(row.flags_detected) : row.flags_detected;
        if (Array.isArray(parsedFlags)) {
          flagTypes = parsedFlags.map(f => typeof f === 'object' && f !== null ? f.type : f);
        }
      } catch (e) {
        console.error("Error parsing flags:", e);
      }
    }
    if (flagTypes.includes("Invalid GSTIN") || flagTypes.includes("GSTIN Format Violation")) {
      invalidGstinCount++;
      hasIssue = true;
      currentIssue = "Invalid GSTIN";
    }
    if (flagTypes.includes("Tax Mismatch") || flagTypes.includes("CGST/SGST Rate Mismatch")) {
      taxMismatchCount++;
      hasIssue = true;
      currentIssue = "Tax Mismatch";
    }
    if (!hasIssue && flagTypes.length > 0) {
      hasIssue = true;
      currentIssue = flagTypes[0];
    }

    // Setup Data for Trend Chart
    const dateKey = row.date || "Unknown";
    if (!trendData[dateKey]) trendData[dateKey] = {
      clean: 0,
      flagged: 0
    };
    if (!hasIssue && flagTypes.length === 0) {
      eligibleInvoices++;
      trendData[dateKey].clean++;
    } else if (hasIssue) {
      trendData[dateKey].flagged++;

      // Setup Data for Vendor Chart
      const vendor = row.vendor_name || "Unknown";
      vendorViolations[vendor] = (vendorViolations[vendor] || 0) + 1;
      const statuses = ["Open Flag", "Under Review"];
      const randomStatus = statuses[Math.floor(Math.random() * statuses.length)];
      let mockedVariance = "₹0.00";
      if (currentIssue === "Tax Mismatch") {
        mockedVariance = "₹" + (Math.floor(Math.random() * 5000) + 500).toFixed(2);
      }
      issuesTableData.push({
        invoiceId: row.invoice_id || "N/A",
        vendorName: vendor,
        issue: currentIssue,
        variance: mockedVariance,
        status: randomStatus
      });
    }
  });

  // Update DOM KPIs
  document.getElementById('kpi-missing-gstin').innerText = missingGstinCount;
  document.getElementById('kpi-invalid-gstin').innerText = invalidGstinCount;
  document.getElementById('kpi-tax-mismatch').innerText = taxMismatchCount;
  document.getElementById('kpi-eligible').innerText = eligibleInvoices.toLocaleString();

  // Update DOM Table
  const tbody = document.querySelector('#compliance-table tbody');
  if (tbody) {
    tbody.innerHTML = '';
    issuesTableData.slice(0, 6).forEach(item => {
      const tr = document.createElement('tr');
      let statusColor = item.status === 'Open Flag' ? '#d32f2f' : '#f57c00';
      let varianceColor = item.variance === '₹0.00' ? '#2e7d32' : '#d32f2f';
      tr.innerHTML = `
                <td style="padding: 8px; border-bottom: 1px solid #eee;"><b>${item.invoiceId}</b></td>
                <td style="padding: 8px; border-bottom: 1px solid #eee;">${item.vendorName}</td>
                <td style="padding: 8px; border-bottom: 1px solid #eee;">${item.issue}</td>
