  border-top-color: var(--alert-red);
}

.kpi p {
  font-size: 36px;
  font-weight: 800;
  margin: 0;
  color: var(--text-main);
}

/* Queue Cards */
.queue-list {
  display: flex;
  flex-direction: column;
  gap: 20px;
}

