const reviewData = {
  kpis: {
    pending: "42",
    high: "18",
    approved: "104",
    override: "12"
  },
  queue: [{
    id: "INV-9942",
    vendor: "Global Tech Imports",
    score: 98,
    riskLevel: "High",
    agent: "Three-Way Match Engine",
    rule: "Quantity Mismatch vs GRN",
    summary: "Invoice quantity (500 units) exceeds Goods Receipt Note (450 units). Potential overbilling of $2,500 detected."
  }, {
    id: "INV-9955",
    vendor: "Acme Logistics",
    score: 92,
    riskLevel: "High",
    agent: "Compliance Agent",
    rule: "Invalid GSTIN Checksum",
    summary: "Vendor GSTIN fails checksum validation. Matches a suspended entity in the master registry."
  }, {
    id: "INV-9961",
    vendor: "NexGen Solutions",
    score: 75,
    riskLevel: "Medium",
    agent: "Rule Engine Agent",
    rule: "Round Dollar Value",
    summary: "Invoice amount is exactly $50,000.00. Round numbers trigger manual review for potential fraud."
  }, {
    id: "INV-9968",
    vendor: "Apex Manufacturing",
    score: 72,
    riskLevel: "Medium",
    agent: "Rule Engine Agent",
    rule: "Weekend Posting",
    summary: "Transaction logged on Sunday at 11:45 PM by User-441. Outside normal business hours."
  }]
};

// Sort queue by risk score descending (Reverse chronological risk)
reviewData.queue.sort((a, b) => b.score - a.score);

// Inject KPIs
document.getElementById('kpi-pending').textContent = reviewData.kpis.pending;
document.getElementById('kpi-high').textContent = reviewData.kpis.high;
document.getElementById('kpi-approved').textContent = reviewData.kpis.approved;
document.getElementById('kpi-override').textContent = reviewData.kpis.override;

// Render Queue
const container = document.getElementById('queue-container');
const renderQueue = () => {
  reviewData.queue.forEach(item => {
    let riskClass = item.riskLevel === "High" ? "risk-high" : "risk-med";
    let badgeClass = item.riskLevel === "High" ? "bg-red" : "bg-orange";
    container.innerHTML += `
      <div class="queue-card ${riskClass}" id="card-${item.id}">
        <div class="queue-header">
          <h4>${item.id} | ${item.vendor}</h4>
          <span class="risk-badge ${badgeClass}">Risk Score: ${item.score}/100</span>
        </div>

        <div class="queue-body">
          <div class="info-group">
            <span class="info-label">Flagging Agent</span>
            <span>🤖 ${item.agent}</span>
            <span class="info-label" style="margin-top: 8px;">Policy Triggered</span>
            <span>🚨 ${item.rule}</span>
          </div>
          <div class="info-group">
            <span class="info-label">AI Audit Summary</span>
            <div class="summary-box">${item.summary}</div>
          </div>
        </div>

        <div class="queue-footer">
          <textarea class="justification-input" placeholder="Enter justification for override or rejection..."></textarea>
          <div class="action-buttons">
            <button class="btn btn-approve" onclick="resolveCard('${item.id}')">Approve</button>
            <button class="btn btn-reject" onclick="resolveCard('${item.id}')">Reject</button>
            <button class="btn btn-override" onclick="resolveCard('${item.id}')">Override Flag</button>
          </div>
        </div>
      </div>
    `;
  });
};
renderQueue();

// Action Logic
window.resolveCard = function (id) {
  const card = document.getElementById(`card-${id}`);
  card.style.opacity = "0.5";
  card.style.pointerEvents = "none";
  card.querySelector('.queue-header h4').innerHTML += " <span style='color:green;'>(Processed)</span>";
};

