  --accent-blue: #0052cc;
  --success-green: #00875a;
  --warning-orange: #ff991f;
  --vibrant-purple: #6554c0;
  --radius: 8px;
  --shadow: 0 4px 6px rgba(0,0,0,0.05);
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  background: var(--bg-color);
  padding: 24px;
  color: var(--text-main);
  margin: 0;
}

.genw-dashboard {
  display: flex;
  flex-direction: column;
  gap: 24px;
}

.row {
  display: grid;
  gap: 24px;
}

.grid-4 {
  grid-template-columns: repeat(4, 1fr);
}

.card {
  background: var(--card-bg);
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  padding: 24px;
  box-shadow: var(--shadow);
}

h3 {
  margin: 0 0 20px 0;
  font-size: 14px;
  font-weight: 600;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.8px;
}

/* KPIs */
.kpi {
  display: flex;
  flex-direction: column;
  justify-content: center;
  text-align: center;
  border-top: 4px solid var(--accent-blue);
}

.kpi.success {
  border-top-color: var(--success-green);
}

.kpi.warning {
  border-top-color: var(--warning-orange);
}

.kpi.alert {
  border-top-color: var(--alert-red);
}

.kpi p {
  font-size: 36px;
  font-weight: 800;
  margin: 0;
  color: var(--text-main);
}

/* Queue Cards */
.queue-list {
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.queue-card {
  border: 1px solid var(--border-color);
  border-left: 6px solid var(--border-color);
  border-radius: var(--radius);
  padding: 20px;
  background: #fafbfc;
  display: flex;
  flex-direction: column;
  gap: 16px;
  transition: transform 0.2s;
}

.queue-card:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow);
}

/* Risk Borders */
.queue-card.risk-high {
  border-left-color: var(--alert-red);
}

.queue-card.risk-med {
  border-left-color: var(--warning-orange);
}

.queue-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  border-bottom: 1px solid var(--border-color);
  padding-bottom: 12px;
}

.queue-header h4 {
  margin: 0;
  font-size: 16px;
  color: var(--text-main);
}

.risk-badge {
  font-size: 12px;
  font-weight: 700;
  padding: 6px 12px;
  border-radius: 4px;
  color: #fff;
}

.bg-red {
  background: var(--alert-red);
}

.bg-orange {
  background: var(--warning-orange);
}

.queue-body {
  display: grid;
  grid-template-columns: 1fr 2fr;
  gap: 16px;
  font-size: 13px;
}

.info-group {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.info-label {
  color: var(--text-muted);
  font-weight: 600;
  text-transform: uppercase;
  font-size: 11px;
}

.summary-box {
  background: #fff;
  border: 1px solid var(--border-color);
  padding: 12px;
  border-radius: 6px;
  font-style: italic;
  color: var(--text-main);
}

.queue-footer {
  display: flex;
  flex-direction: column;
  gap: 12px;
  border-top: 1px solid var(--border-color);
  padding-top: 16px;
}

.justification-input {
  width: 100%;
  padding: 10px;
  border: 1px solid var(--border-color);
  border-radius: 4px;
  font-family: inherit;
  resize: vertical;
  min-height: 40px;
}

.action-buttons {
  display: flex;
  gap: 12px;
}

/* Buttons */
.btn {
  padding: 8px 16px;
  border: none;
  border-radius: 4px;
  font-weight: 600;
  cursor: pointer;
  color: #fff;
  transition: opacity 0.2s;
}

.btn:hover {
  opacity: 0.9;
}

.btn-approve {
  background: var(--success-green);
}

.btn-reject {
  background: var(--alert-red);
}

.btn-override {
  background: var(--vibrant-purple);
}

