appsmith.onReady(() => {
  const rawData = appsmith.model.transactions;
  if (!rawData || rawData.length === 0) {
    document.body.innerHTML = '<div style="padding: 20px; font-family: sans-serif; color: #666;">Waiting for database records...</div>';
    return;
  }

  // 1. Initialize Trackers
  let totalAnalyzed = rawData.length;
  let highRiskCount = 0;
  let policyExceptions = 0;
  let complianceGaps = 0;
  let exceptionLogData = [];

  // 2. Process the Data
  rawData.forEach(row => {
    let risk = (row.risk_rating || "").toUpperCase();
    let isException = false;
    let exceptionCategory = "Unknown Exception";

    // KPI Logic based on Risk Ratings
    if (risk === "CRITICAL" || risk === "HIGH") {
      highRiskCount++;
      isException = true;
    }
    if (risk === "CRITICAL" || risk === "HIGH" || risk === "MEDIUM") {
      policyExceptions++;
      isException = true;
    }
    if (risk === "PENDING") {
      complianceGaps++;
      isException = true;
      exceptionCategory = "Audit Pending / Missing Data";
    }

    // Only process rows for the table if they are exceptions
    if (isException) {
      // Extract the specific flag type from flags_detected JSON if it exists
      let flags = [];
      if (row.flags_detected) {
        try {
          flags = typeof row.flags_detected === 'string' ? JSON.parse(row.flags_detected) : row.flags_detected;
          if (flags.length > 0 && flags[0].type) {
            exceptionCategory = flags[0].type;
          }
        } catch (e) {
          console.error("Parse error:", e);
        }
      } else if (risk === "CRITICAL" || risk === "HIGH") {
        exceptionCategory = "High Risk Validation Failure";
      }

      // MOCKING: Randomly assign a resolution status
      const statuses = ["Escalated to Mgr", "Pending Review", "Overridden"];
      const randomStatus = statuses[Math.floor(Math.random() * statuses.length)];

      // Color coding for the Risk Level column
      let riskColor = risk === 'CRITICAL' || risk === 'HIGH' ? '#d32f2f' : risk === 'MEDIUM' ? '#f57c00' : '#1976d2';

      // Store clean data object for both the Table and the CSV Export
      exceptionLogData.push({
        txnId: row.transaction_id || "N/A",
        vendor: row.vendor_name || "Unknown",
        category: exceptionCategory,
        risk: risk,
        riskColor: riskColor,
        status: randomStatus,
        amount: row.amount || "0",
        date: row.transaction_date || "N/A",
        recommendedAction: row.recommended_action || "Pending"
      });
    }
  });

  // 3. Update DOM KPIs
  document.getElementById('kpi-total').innerText = totalAnalyzed.toLocaleString();
  document.getElementById('kpi-high-risk').innerText = highRiskCount.toLocaleString();
  document.getElementById('kpi-exceptions').innerText = policyExceptions.toLocaleString();
  document.getElementById('kpi-gaps').innerText = complianceGaps.toLocaleString();

  // 4. Update DOM Table
  const tbody = document.querySelector('#exception-table tbody');
  if (tbody) {
    tbody.innerHTML = '';
    exceptionLogData.forEach(item => {
      const tr = document.createElement('tr');

      // Apply specific UI styling based on status
      let statusStyle = "";
      if (item.status === 'Escalated to Mgr') statusStyle = "color: #2e7d32; background: #e8f5e9; padding: 4px 8px; border-radius: 4px; font-weight: bold; font-size: 12px;";else if (item.status === 'Pending Review') statusStyle = "color: #1976d2; background: #e3f2fd; padding: 4px 8px; border-radius: 4px; font-weight: bold; font-size: 12px;";else if (item.status === 'Overridden') statusStyle = "color: #7b1fa2; background: #f3e5f5; padding: 4px 8px; border-radius: 4px; font-weight: bold; font-size: 12px;";
      tr.innerHTML = `
                <td style="padding: 10px 8px; border-bottom: 1px solid #eee;"><b>${item.txnId}</b></td>
                <td style="padding: 10px 8px; border-bottom: 1px solid #eee;">${item.vendor}</td>
                <td style="padding: 10px 8px; border-bottom: 1px solid #eee;">${item.category}</td>
                <td style="padding: 10px 8px; border-bottom: 1px solid #eee; color: ${item.riskColor}; font-weight: bold;">${item.risk}</td>
                <td style="padding: 10px 8px; border-bottom: 1px solid #eee;"><span style="${statusStyle}">${item.status}</span></td>
            `;
      tbody.appendChild(tr);
    });
  }

  // 5. Setup CSV Export Feature
  document.getElementById('btn-export-csv').addEventListener('click', () => {
    // Prepare CSV Headers
    const headers = ["Transaction ID", "Vendor Name", "Exception Category", "Risk Level", "Resolution Status", "Amount", "Date", "Recommended System Action"];

    // Map table data to CSV rows
    const csvRows = exceptionLogData.map(row => [row.txnId, `"${row.vendor}"`,
    // Wrap in quotes to handle spaces/commas safely
    `"${row.category}"`, row.risk, row.status, row.amount, row.date, row.recommendedAction]);

    // Combine into CSV string
    let csvContent = "data:text/csv;charset=utf-8," + headers.join(",") + "\n" + csvRows.map(e => e.join(",")).join("\n");

    // Trigger Download
    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", `Audit_Exception_Report_${new Date().toISOString().split('T')[0]}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  });

  // 6. Setup PDF Export Feature
  document.getElementById('btn-export-pdf').addEventListener('click', () => {
    // Leverages native browser print functionality. 
    // The CSS <style> block in the HTML hides the buttons and ensures only the report prints to the PDF.
    window.print();
  });
});

