let allVendors = [];
let visibleCount = 5;
let kpiData = {};
appsmith.onReady(() => {
  let rawData = appsmith.model;
  let vendors = [];
  if (rawData && Array.isArray(rawData)) vendors = rawData;else if (rawData && rawData.vendors) vendors = rawData.vendors;
  if (!vendors || vendors.length === 0) {
    document.body.innerHTML = '<div style="padding: 20px; font-family: sans-serif; color: #666;">Waiting for database records...</div>';
    return;
  }

  // --- DATA LOGIC FROM JS #1 (unchanged) ---
  let screened = vendors.length;
  let verified = 0,
    pending = 0,
    risk = 0;
  allVendors = vendors.map(v => {
    let score = "Pending";
    let scoreClass = "score-med";
    const rating = (v.risk_rating || '').toLowerCase();
    if (rating === 'low') {
      score = "98/100";
      scoreClass = "score-good";
      if (!v.blacklist_status) verified++;
    } else if (rating === 'medium') {
      score = "65/100";
      scoreClass = "score-med";
      pending++;
    } else if (rating === 'high') {
      score = "21/100";
      scoreClass = "score-bad";
      risk++;
    } else {
      pending++;
    }
    if (v.blacklist_status) risk++;
    const gstinStatus = v.official_gstin ? "Active" : "Mismatch";
    const gstinClass = v.official_gstin ? "pass" : "warn";
    const watchlistStatus = v.blacklist_status ? "Flagged" : "Clear";
    const watchlistClass = v.blacklist_status ? "fail" : "pass";
    return {
      id: v.vendor_id,
      name: v.vendor_name || "Unknown Vendor",
      score,
      scoreClass,
      flow: [{
        name: "KYC Check",
        icon: "🏢",
        status: "Verified",
        statClass: "pass"
      }, {
        name: "GSTIN Valid",
        icon: "📑",
        status: gstinStatus,
        statClass: gstinClass
      }, {
        name: "Bank Match",
        icon: "🏦",
        status: "Matched",
        statClass: "pass"
      }, {
        name: "Watchlist",
        icon: "🔍",
        status: watchlistStatus,
        statClass: watchlistClass
      }]
    };
  });
  kpiData = {
    screened: screened.toLocaleString(),
    verified: verified.toLocaleString(),
    pending: pending.toLocaleString(),
    risk: risk.toLocaleString()
  };

  // --- POPULATE KPIs (JS #2 style — elements already exist in HTML tab) ---
  document.getElementById('kpi-screened').textContent = kpiData.screened;
  document.getElementById('kpi-verified').textContent = kpiData.verified;
  document.getElementById('kpi-pending').textContent = kpiData.pending;
  document.getElementById('kpi-risk').textContent = kpiData.risk;

  // --- RENDER PIPELINE (JS #2 style) ---
  const container = document.getElementById('vendor-container');
  const renderVendors = () => {
    const visibleVendors = allVendors.slice(0, visibleCount);
    container.innerHTML = ''; // clear before re-render to avoid duplicates

    visibleVendors.forEach(v => {
      let stepsHTML = v.flow.map((step, index) => `
                <div class="flow-step">
                    <span class="step-icon">${step.icon}</span>
                    <span class="step-label">${step.name}</span>
                    <span class="step-status ${step.statClass}">${step.status}</span>
                </div>
                ${index < 3 ? '<div class="arrow">➔</div>' : ''}
            `).join('');
      container.innerHTML += `
                <div class="vendor-card">
                    <div class="vendor-header">
                        <div class="vendor-info">
                            <h4>${v.name}</h4>
                            <span>Vendor ID: ${v.id}</span>
                        </div>
                        <div class="final-score ${v.scoreClass}">Risk Score: ${v.score}</div>
                    </div>
                    <div class="flow-pipeline">
                        ${stepsHTML}
                    </div>
                </div>
            `;
    });
  };
  renderVendors();

  // --- LOAD MORE (JS #2 style) ---
  document.getElementById('btn-load-more').addEventListener('click', function () {
    this.textContent = "Loading...";
    setTimeout(() => {
      visibleCount += 5;
      renderVendors();
      if (visibleCount >= allVendors.length) {
        this.textContent = "No More Records";
        this.disabled = true;
        this.style.opacity = "0.5";
      } else {
        this.textContent = "Load More Records ↻";
      }
    }, 800);
  });
});

