  initialMessage: "<strong>Audit Context Loaded: INV-9942</strong><br>I have analyzed the transaction. The invoice quantity (500 units) exceeds the Goods Receipt Note (450 units). Potential overbilling risk detected. How would you like to investigate?",
  suggestions: ["Summarize financial impact", "Show historical vendor anomalies", "Draft escalation email to VEND1011"],
  context: {
    recordHtml: `
      <span><strong>Entity:</strong> Global Tech Imports</span>
      <span><strong>Transaction ID:</strong> INV-9942</span>
      <span><strong>Linked PO:</strong> PO-4412</span>
      <span><strong>Risk Score:</strong> 98/100</span>
      <span class="status-pill status-high">Critical Flag</span>
    `,
    evidenceLinks: ["📄 <a href='#'>Source_Invoice_9942.pdf (Page 1)</a>", "📦 <a href='#'>Warehouse_GRN_4412.xml</a>", " Policy: <a href='#'>Sec 4.1 - Three-Way Matching</a>", "📊 Logs: <a href='#'>Vendor_History_Report.csv</a>"]
  }
};
const history = document.getElementById('chat-history');
const suggestionsBox = document.getElementById('chat-suggestions');
const inputField = document.getElementById('chat-input');

// Render Initial State
function initAssistant() {
  // Context
  document.getElementById('active-record').innerHTML = assistantData.context.recordHtml;
  const evList = document.getElementById('evidence-list');
  assistantData.context.evidenceLinks.forEach(link => {
    evList.innerHTML += `<li>${link}</li>`;
  });

  // Bot Message
  appendMessage('bot', assistantData.initialMessage);

  // Suggestions
  assistantData.suggestions.forEach(s => {
    suggestionsBox.innerHTML += `<button class="pill-suggestion" onclick="fillInput('${s}')">${s}</button>`;
  });
}
