:root {
  --bg-color: #f7f9fa;
  --card-bg: #ffffff;
  --text-main: #2A2A2A;
  --text-muted: #5e6c84;
  --border-color: #dfe1e6;
  --alert-red: #de350b;
  --accent-blue: #0052cc;
  --success-green: #00875a;
  --warning-orange: #ff991f;
  --vibrant-purple: #6554c0;
  --chat-bot: #f4f5f7;
  --chat-user: #e6effc;
  --radius: 8px;
  --shadow: 0 4px 6px rgba(0,0,0,0.05);
}

body { font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif; background: var(--bg-color); padding: 24px; color: var(--text-main); margin: 0; }

.assistant-layout { display: grid; grid-template-columns: 2fr 1fr; gap: 24px; height: 80vh; }
.card { background: var(--card-bg); border: 1px solid var(--border-color); border-radius: var(--radius); padding: 20px; box-shadow: var(--shadow); }
h3 { margin: 0; font-size: 14px; font-weight: 600; color: var(--text-muted); text-transform: uppercase; letter-spacing: 0.8px; }

/* Chat Container */
.chat-container { display: flex; flex-direction: column; gap: 16px; height: 100%; box-sizing: border-box; }
.chat-header { display: flex; justify-content: space-between; align-items: center; border-bottom: 1px solid var(--border-color); padding-bottom: 12px; }
.status-indicator { color: var(--success-green); font-size: 12px; font-weight: 600; }

.chat-history { flex: 1; overflow-y: auto; display: flex; flex-direction: column; gap: 16px; padding: 10px 0; }
.msg { padding: 12px 16px; border-radius: 12px; font-size: 13px; max-width: 80%; line-height: 1.5; }
.msg-bot { background: var(--chat-bot); align-self: flex-start; border-bottom-left-radius: 4px; border: 1px solid var(--border-color); }
.msg-user { background: var(--chat-user); align-self: flex-end; border-bottom-right-radius: 4px; border: 1px solid #cce0ff; color: var(--accent-blue); font-weight: 500; }

/* Suggestions */
.chat-suggestions { display: flex; gap: 8px; flex-wrap: wrap; }
.pill-suggestion { background: #fff; border: 1px solid var(--vibrant-purple); color: var(--vibrant-purple); padding: 6px 12px; border-radius: 16px; font-size: 12px; cursor: pointer; transition: all 0.2s; }
.pill-suggestion:hover { background: var(--vibrant-purple); color: #fff; }

/* Input */
.chat-input-area { display: flex; gap: 12px; border-top: 1px solid var(--border-color); padding-top: 16px; }
#chat-input { flex: 1; padding: 12px; border: 1px solid var(--border-color); border-radius: var(--radius); font-size: 13px; outline: none; }
#chat-input:focus { border-color: var(--accent-blue); }
.btn-send { background: linear-gradient(135deg, var(--vibrant-purple) 0%, var(--accent-blue) 100%); color: white; border: none; padding: 0 24px; border-radius: var(--radius); font-weight: 600; cursor: pointer; }

/* Context Panel */
.context-container { display: flex; flex-direction: column; gap: 24px; }
.context-details { margin-top: 16px; font-size: 13px; display: flex; flex-direction: column; gap: 8px; }
.context-details strong { color: var(--text-muted); }
.evidence-list { list-style: none; padding: 0; margin: 16px 0 0 0; display: flex; flex-direction: column; gap: 12px; }
.evidence-list li { font-size: 13px; display: flex; align-items: center; gap: 8px; }
.evidence-list a { color: var(--accent-blue); text-decoration: none; font-weight: 500; }
.evidence-list a:hover { text-decoration: underline; }

.status-pill { padding: 4px 8px; border-radius: 12px; font-size: 11px; font-weight: 600; display: inline-block; width: fit-content; margin-top: 4px; }
.status-high { background: #ffebe6; color: var(--alert-red); }

