// Render Initial State
function initAssistant() {
  // Context
  document.getElementById('active-record').innerHTML = assistantData.context.recordHtml;

  const evList = document.getElementById('evidence-list');
  assistantData.context.evidenceLinks.forEach(link => {
    evList.innerHTML += `<li>${link}</li>`;
  });

  // Bot Message
  appendMessage('bot', assistantData.initialMessage);

  // Suggestions
  assistantData.suggestions.forEach(s => {
    suggestionsBox.innerHTML += `<button class="pill-suggestion" onclick="fillInput('${s}')">${s}</button>`;
  });
}

function appendMessage(sender, text) {
  const msgDiv = document.createElement('div');
  msgDiv.className = `msg msg-${sender}`;
  msgDiv.innerHTML = text;
  history.appendChild(msgDiv);
  history.scrollTop = history.scrollHeight;
}

// Updated: Autofills the chat input instead of auto-sending
function fillInput(text) {
    // Hide the suggestions box to clear up screen space
    if (suggestionsBox) {
        suggestionsBox.style.display = "none";
    }

    // Autofill the input field
    inputField.value = text;

    // Automatically put the cursor in the input field so you can just hit Enter
    inputField.focus();
}

// Added: Simple Markdown to HTML parser for LLM formatting
function parseMarkdown(text) {
    if (!text) return "";
    return text
        .replace(/^### (.*$)/gim, '<h3>$1</h3>')
        .replace(/^## (.*$)/gim, '<h2>$1</h2>')
        .replace(/^# (.*$)/gim, '<h1>$1</h1>')
        .replace(/\*\*(.*)\*\*/gim, '<strong>$1</strong>')
        .replace(/\*(.*)\*/gim, '<em>$1</em>')
        .replace(/`(.*?)`/gim, '<code style="background:#eee; padding:2px 4px; border-radius:3px;">$1</code>')
        .replace(/\n/gim, '<br>');
}

