      if (rating === 'low') {
        score = "98/100";
        scoreClass = "score-good";
      } else if (rating === 'medium') {
        score = "65/100";
        scoreClass = "score-med";
      } else if (rating === 'high') {
        score = "21/100";
        scoreClass = "score-bad";
      }
      const gstinStatus = v.official_gstin ? "Active" : "Mismatch";
      const gstinClass = v.official_gstin ? "pass" : "warn";
      const watchlistStatus = v.blacklist_status ? "Flagged" : "Clear";
      const watchlistClass = v.blacklist_status ? "fail" : "pass";
      return {
        id: v.vendor_id,
        name: v.vendor_name || "Unknown Vendor",
        score: score,
        scoreClass: scoreClass,
        flow: [{
          name: "KYC Check",
          icon: "🏢",
          status: "Verified",
          statClass: "pass"
        }, {
          name: "GSTIN Valid",
          icon: "📑",
          status: gstinStatus,
          statClass: gstinClass
        }, {
