          icon: "🏦",
          status: "Matched",
          statClass: "pass"
        }, {
          name: "Watchlist",
          icon: "🔍",
          status: watchlistStatus,
          statClass: watchlistClass
        }]
      };
    });
    return {
      kpis: {
        screened: Number(kpis.screened || 0).toLocaleString(),
        verified: Number(kpis.verified || 0).toLocaleString(),
        pending: Number(kpis.pending || 0).toLocaleString(),
        risk: Number(kpis.risk || 0).toLocaleString()
      },
      companies: formattedCompanies
    };
  } catch (err) {
